//! Minimal Aliyun OSS client (PutObject + short-lived signed GET URLs).
//!
//! Matches the reference Go server's private-bucket publishing flow: release
//! artifacts live in a private bucket and clients download through per-request
//! signed URLs regenerated by `GET /api/versions/latest`.

use base64::Engine;
use hmac::{Hmac, Mac};
use percent_encoding::{percent_encode, NON_ALPHANUMERIC};
use sha1::Sha1;

/// OSS credentials and bucket configuration (injected via env, never logged).
#[derive(Debug, Clone)]
pub struct OssConfig {
    pub access_key_id: String,
    pub access_key_secret: String,
    pub bucket: String,
    pub endpoint: String,
}

impl OssConfig {
    /// Builds config from `OSS_ACCESS_KEY_ID` / `OSS_ACCESS_KEY_SECRET` /
    /// `OSS_BUCKET` / `OSS_ENDPOINT` env vars. Returns `None` when any required
    /// variable is missing (publishing with file uploads is then disabled).
    pub fn from_env() -> Option<Self> {
        let access_key_id = std::env::var("OSS_ACCESS_KEY_ID").ok()?;
        let access_key_secret = std::env::var("OSS_ACCESS_KEY_SECRET").ok()?;
        let bucket = std::env::var("OSS_BUCKET").ok()?;
        if access_key_id.is_empty() || access_key_secret.is_empty() || bucket.is_empty() {
            return None;
        }
        let endpoint =
            std::env::var("OSS_ENDPOINT").unwrap_or_else(|_| "oss-cn-hangzhou.aliyuncs.com".into());
        Some(Self {
            access_key_id,
            access_key_secret,
            bucket,
            endpoint,
        })
    }

    fn object_url(&self, key: &str) -> String {
        format!("https://{}.{}/{}", self.bucket, self.endpoint, key)
    }

    fn signature(&self, string_to_sign: &str) -> String {
        let mut mac = <Hmac<Sha1> as Mac>::new_from_slice(self.access_key_secret.as_bytes())
            .expect("oss hmac key");
        mac.update(string_to_sign.as_bytes());
        base64::engine::general_purpose::STANDARD.encode(mac.finalize().into_bytes())
    }

    fn now_gmt() -> String {
        chrono::Utc::now()
            .format("%a, %d %b %Y %H:%M:%S GMT")
            .to_string()
    }

    /// Uploads `data` to the private bucket under `key`.
    ///
    /// OSS authorization: `OSS <id>:<base64(hmac-sha1(secret, string_to_sign))>`
    /// with `string_to_sign = "PUT\n<md5>\n<type>\n<date>\n/resource"`.
    /// Neither Content-MD5 nor Content-Type is sent, so both slots are empty.
    pub async fn put_object(&self, key: &str, data: &[u8]) -> Result<(), String> {
        let date = Self::now_gmt();
        let canonical = format!("/{}/{}", self.bucket, key);
        let string_to_sign = format!("PUT\n\n\n{date}\n{canonical}");
        let signature = self.signature(&string_to_sign);
        let authorization = format!("OSS {}:{}", self.access_key_id, signature);

        let response = reqwest::Client::new()
            .put(self.object_url(key))
            .header("Authorization", authorization)
            .header("Date", date)
            .header("Content-Length", data.len().to_string())
            .body(data.to_vec())
            .send()
            .await
            .map_err(|e| format!("oss put failed: {e}"))?;
        if !response.status().is_success() {
            let status = response.status();
            let body = response.text().await.unwrap_or_default();
            return Err(format!("oss put failed: {status}: {body}"));
        }
        Ok(())
    }

    /// Short-lived GET URL for a private object (`expires_in_secs`).
    ///
    /// `string_to_sign = "GET\n\n\n<expires>\n/resource"`, matching OSS signed
    /// URL semantics (the expiry takes the Date slot).
    pub fn signed_get_url(&self, key: &str, expires_in_secs: i64) -> Result<String, String> {
        let expires = chrono::Utc::now().timestamp() + expires_in_secs;
        let canonical = format!("/{}/{}", self.bucket, key);
        let string_to_sign = format!("GET\n\n\n{expires}\n{canonical}");
        let signature = self.signature(&string_to_sign);
        Ok(format!(
            "{}?OSSAccessKeyId={}&Expires={}&Signature={}",
            self.object_url(key),
            percent_encode(self.access_key_id.as_bytes(), NON_ALPHANUMERIC),
            expires,
            percent_encode(signature.as_bytes(), NON_ALPHANUMERIC),
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn signed_url_matches_aliyun_docs_vector() {
        // Documented example: AccessKeyId=foo, AccessKeySecret=bar,
        // bucket=examplebucket, key=baz.txt, expires=1443391118.
        let cfg = OssConfig {
            access_key_id: "foo".into(),
            access_key_secret: "bar".into(),
            bucket: "examplebucket".into(),
            endpoint: "oss-cn-hangzhou.aliyuncs.com".into(),
        };
        let canonical = "/examplebucket/baz.txt";
        let string_to_sign = format!("GET\n\n\n1443391118\n{canonical}");
        let sig = cfg.signature(&string_to_sign);
        assert_eq!(sig, "+9sclHSMFRSWDG5L3mPazyk1mW4=");
    }

    #[test]
    fn from_env_requires_all_fields() {
        std::env::remove_var("OSS_ACCESS_KEY_ID");
        std::env::remove_var("OSS_ACCESS_KEY_SECRET");
        std::env::remove_var("OSS_BUCKET");
        std::env::remove_var("OSS_ENDPOINT");
        assert!(OssConfig::from_env().is_none());

        std::env::set_var("OSS_ACCESS_KEY_ID", "id");
        assert!(OssConfig::from_env().is_none());
        std::env::set_var("OSS_ACCESS_KEY_SECRET", "secret");
        std::env::set_var("OSS_BUCKET", "bucket");
        let cfg = OssConfig::from_env().expect("config");
        assert_eq!(cfg.endpoint, "oss-cn-hangzhou.aliyuncs.com");
        std::env::remove_var("OSS_ACCESS_KEY_ID");
        std::env::remove_var("OSS_ACCESS_KEY_SECRET");
        std::env::remove_var("OSS_BUCKET");
    }
}
